391.     #[verifier::type_invariant]
392.     spec fn wf_write_handle(self) -> bool {
393.         equal(self.perm@.id(), self.rwlock.cell.id()) && self.perm@.is_uninit() && equal(
394.             self.handle@.instance_id(),
395.             self.rwlock.inst@.id(),
396.         ) && self.rwlock.wf()
397.     }
